import {copy,KEYS,noteName} from './music.js';
import {planPatternTransform} from './pattern-transform.js';
const $=s=>document.querySelector(s),escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),bar=n=>+(n/4+1).toFixed(4);
export function createPatternTransformUI({getProject,getRevision,commit,protectedChange,modal,toast,clipSVG,library}){
 let flow=0;
 return function show(patternId){
  const before=copy(getProject()),source=before.patterns?.find(p=>p.id===patternId),at=getRevision(),ticket=++flow;if(!source)return toast('请先选择仍存在的源乐句');let result,busy=false,refPage=0,notePage=0;
  modal('共享乐句变换 · 明确同步全部实例',`<div class="pattern-transform-form"><p><strong>${escape(source.name)}</strong> · 当前 ${source.length/4} 小节、${source.notes.length} 个源音符。这里改的是<strong>库中源乐句与全部关联块</strong>；独立副本不变。不想同步，请取消后用“乐句变换”。</p><div class="phrase-presets"><button class="quiet" data-shared-preset="half"><strong>紧凑一倍</strong><small>源与全部实例同时缩短</small></button><button class="quiet" data-shared-preset="double"><strong>舒展一倍</strong><small>全体检查碰撞与尾边界</small></button><button class="quiet" data-shared-preset="reverse"><strong>倒过来</strong><small>音符倒序 · 不是音频反放</small></button></div><div class="phrase-fields"><label for="shared-ratio">节奏与长度倍数<select id="shared-ratio" aria-label="共享节奏倍数"><option value="0.5">× 0.5 · 紧凑</option><option value="1" selected>× 1 · 保持</option><option value="2">× 2 · 舒展</option></select></label><label for="shared-transpose">整体移调（半音）<input id="shared-transpose" type="number" min="-24" max="24" step="1" value="0" ${source.kind==='drum'?'disabled':''}></label></div><label class="check-label"><input id="shared-reverse" type="checkbox">按源长度倒序音符，同时保持全部实例起点</label><label class="modal-label" for="shared-scale">移调后吸附到最近调内音</label><select id="shared-scale" ${source.kind==='drum'?'disabled':''}><option value="keep">不吸附，保留半音间距</option>${Object.keys(KEYS).map(k=>`<option value="${k}">${escape(k)}${k===before.key?' · 当前工程':''}</option>`).join('')}</select><label class="modal-label" for="shared-timing">微偏移</label><select id="shared-timing"><option value="follow">随倍数与倒序方向变换</option><option value="keep">保留原拍数与方向（越界仍拒绝）</option><option value="clear">清除源及全部实例微偏移</option></select><label class="check-label"><input id="shared-extend" type="checkbox">明确空白延长工程以容纳全部实例（最多 64 小节）</label><div id="shared-transform-summary" class="performance-summary" aria-live="polite"></div><div id="shared-transform-refs"></div><details class="performance-table"><summary>源音符前后 · 相对源起点</summary><div id="shared-transform-notes"></div></details><div id="shared-transform-error" role="status" class="export-progress"></div><details class="modal-notice"><summary>共享与局部的边界</summary><p>这里不是 LLM 变奏或和声改写。节奏倍数同时缩放源长度、相对起点与音符长度；倒序为源长 − 旧相对起点 − 旧长度，不同长度和弦可能不再同时起音。调内吸附就近，等距取低，可合并原不同音高。鼓不变音高。</p><p>源 / 源音符 IDs、全部实例 IDs / 起点 / 名称 / 静音 / 关联保持；改变所有关联缓存，包含静音或不独奏的轨道。独立块、其他源、音色、混音、BPM / 调性 / 摇摆、段落与练习范围不变。缩短释放区域留白；加长不得碰到任何旧块，不挤走后面的内容；有一处非法，全体拒绝。全局摇摆仍按新名义网格应用，不保证实际时间严格倍乘或镜像。</p><p>只有明确允许才空白延长，不自动重复其它音乐。先备份，再一次应用与撤销，不自动试听。预设替换草稿，不自动应用；未使用的源也可变换，但不直接产生声音。</p></details></div>`,'<button class="quiet" data-close>取消</button><button class="accent" id="shared-transform-apply">备份并同步全部实例</button>');
  const d=$('#modal'),root=$('.pattern-transform-form');d.addEventListener('close',()=>{if(ticket===flow)++flow},{once:true});
  const revisionGuard=()=>{if(at!==getRevision())throw Error('工程已改变，请重新打开共享乐句变换。')};
  const guard=()=>{revisionGuard();if(ticket!==flow||!root.isConnected||!d.open)throw Error('窗口已改变，没有应用旧共享变换。')};
  const fail=e=>{if(root.isConnected){$('#shared-transform-error').textContent=e.message;$('#shared-transform-apply').disabled=true}else toast(e.message)};
  function refs(){const list=result?.affected||[],pages=Math.max(1,Math.ceil(list.length/6));refPage=Math.min(refPage,pages-1);$('#shared-transform-refs').innerHTML=`<div class="shared-transform-refs"><h4>全部关联音块 · ${list.length} 个${list.length?'':'（只改库中源）'}</h4>${list.slice(refPage*6,refPage*6+6).map(r=>`<div class="shared-transform-ref"><strong>${escape(r.trackName)} · ${escape(r.clipName)}</strong><small>第 ${bar(r.start)} 小节起不动 · ${r.lengthBefore/4} → ${r.lengthAfter/4} 小节 · ${r.noteCount} 音符${r.muted?' · 块静音':''}${r.trackMuted?' · 轨道静音':''}${r.trackSolo?' · 独奏':''}</small></div>`).join('')}<div class="performance-pagination"><button class="quiet compact" id="shared-ref-prev" ${refPage===0?'disabled':''}>前一页实例</button><span>${refPage+1} / ${pages} 页</span><button class="quiet compact" id="shared-ref-next" ${refPage===pages-1?'disabled':''}>后一页实例</button></div></div>`;$('#shared-ref-prev').onclick=()=>{if(!busy){refPage--;refs()}};$('#shared-ref-next').onclick=()=>{if(!busy){refPage++;refs()}}}
  function notes(){const list=result?.changes||[],pages=Math.max(1,Math.ceil(list.length/12));notePage=Math.min(notePage,pages-1);$('#shared-transform-notes').innerHTML=`<div class="performance-table-scroll"><table><thead><tr><th>音高</th><th>相对拍数</th><th>长度（拍）</th><th>微偏移（拍）</th></tr></thead><tbody>${list.slice(notePage*12,notePage*12+12).map(x=>`<tr><th>${noteName(x.before.pitch)} → ${noteName(x.after.pitch)}</th><td>${x.before.start} → ${x.after.start}</td><td>${x.before.duration} → ${x.after.duration}</td><td>${x.before.timingOffset||0} → ${x.after.timingOffset||0}</td></tr>`).join('')||'<tr><td colspan="4">源音符没有变化。</td></tr>'}</tbody></table></div><div class="performance-pagination"><button class="quiet compact" id="shared-note-prev" ${notePage===0?'disabled':''}>前一页源音符</button><span>${notePage+1} / ${pages} 页 · ${list.length} 个变化</span><button class="quiet compact" id="shared-note-next" ${notePage===pages-1?'disabled':''}>后一页源音符</button></div>`;$('#shared-note-prev').onclick=()=>{if(!busy){notePage--;notes()}};$('#shared-note-next').onclick=()=>{if(!busy){notePage++;notes()}}}
  function update(){result=null;try{guard();result=planPatternTransform(before,patternId,{controls:{ratio:+$('#shared-ratio').value,reverse:$('#shared-reverse').checked,transpose:$('#shared-transpose').value===''?NaN:+$('#shared-transpose').value,scale:$('#shared-scale').value,timing:$('#shared-timing').value,extend:$('#shared-extend').checked}});const r=result.report;refPage=notePage=0;
    $('#shared-transform-summary').innerHTML=`<span class="eyebrow">静音草稿 · 共享源，不是局部块</span><h3>${r.changedSourceNotes} 个源音符改变 · 同步 ${r.instances} 个实例</h3><div class="chord-note-map" style="--track-color:#b7d889">${clipSVG({notes:result.sourceAfter.notes},0,result.sourceAfter.length)}</div><p>源与实例长度 ${r.lengthBefore/4} → ${r.lengthAfter/4} 小节；保留 ${r.sourceNotes} 个源音符 / ${r.instanceNotes} 个实例音符与关联。<br>音高 ${r.pitchChanged} · 起点 ${r.moved} · 长度 ${r.durationChanged} · 微偏移 ${r.timingChanged}。</p>${r.barsBefore!==r.barsAfter?`<p>工程明确 ${r.barsBefore} → ${r.barsAfter} 小节，仅空白延长；标签与练习范围保持。</p>`:''}<p>相关同音重叠 ${result.tracks.reduce((n,t)=>n+t.overlapsBefore,0)} → ${result.tracks.reduce((n,t)=>n+t.overlapsAfter,0)} 对，仅提示，不删音符。当前工程尚未改变。</p>`;
    $('#shared-transform-error').textContent=r.changed?'':'草稿没有变化，可取消返回。';$('#shared-transform-apply').disabled=busy||!r.changed;refs();notes();
   }catch(e){$('#shared-transform-summary').textContent='没有应用任何共享变换，请调整参数。';$('#shared-transform-refs').innerHTML='';$('#shared-transform-notes').innerHTML='';fail(e)}}
  root.querySelectorAll('input,select').forEach(n=>n.oninput=()=>{if(!busy)update()});root.querySelectorAll('[data-shared-preset]').forEach(n=>n.onclick=()=>{if(busy)return;const preset=n.dataset.sharedPreset;$('#shared-ratio').value=preset==='half'?'0.5':preset==='double'?'2':'1';$('#shared-reverse').checked=preset==='reverse';$('#shared-transpose').value=0;$('#shared-scale').value='keep';$('#shared-timing').value='follow';$('#shared-extend').checked=false;update()});
  $('#shared-transform-apply').onclick=async()=>{try{guard();if(!result?.report.changed||busy)throw Error('请先得到有变化的合法共享预览');const planned=result;busy=true;root.querySelectorAll('input,select,button').forEach(n=>n.disabled=true);$('#shared-transform-apply').disabled=true;$('#shared-transform-error').textContent='正在保存共享变换前版本，工程尚未改变…';let applied=false;
    await protectedChange(({fallback=false}={})=>{try{fallback?revisionGuard():guard();if(commit(planned.project)){applied=true;d.close();toast(`已变换共享源并同步 ${planned.report.instances} 个实例，可一次撤销。独立块保持。`)}}catch(e){toast(e.message)}},'共享乐句变换前 · '+source.name);
    if(!applied&&root.isConnected&&d.open){busy=false;root.querySelectorAll('input,select,button').forEach(n=>n.disabled=false);if(source.kind==='drum'){$('#shared-transpose').disabled=true;$('#shared-scale').disabled=true}update()}
   }catch(e){fail(e)}};update();
 };
}
